#![allow(clippy::excessive_precision)]

/// Minimal complex number (matches C99 `float complex` naive arithmetic).
#[derive(Clone, Copy, Debug)]
pub struct Cf {
    pub re: f32,
    pub im: f32,
}

impl Cf {
    pub const fn new(re: f32, im: f32) -> Cf {
        Cf { re, im }
    }
    #[inline(always)]
    pub fn conj(self) -> Cf {
        Cf::new(self.re, -self.im)
    }
}

impl core::ops::Add for Cf {
    type Output = Cf;
    #[inline(always)]
    fn add(self, o: Cf) -> Cf {
        Cf::new(self.re + o.re, self.im + o.im)
    }
}
impl core::ops::Sub for Cf {
    type Output = Cf;
    #[inline(always)]
    fn sub(self, o: Cf) -> Cf {
        Cf::new(self.re - o.re, self.im - o.im)
    }
}
impl core::ops::Mul for Cf {
    type Output = Cf;
    #[inline(always)]
    fn mul(self, o: Cf) -> Cf {
        // naive C99 complex multiply (matches -ffast-math / limited-range)
        Cf::new(self.re * o.re - self.im * o.im, self.re * o.im + self.im * o.re)
    }
}
impl core::ops::Mul<f32> for Cf {
    type Output = Cf;
    #[inline(always)]
    fn mul(self, s: f32) -> Cf {
        Cf::new(self.re * s, self.im * s)
    }
}
impl core::ops::Mul<Cf> for f32 {
    type Output = Cf;
    #[inline(always)]
    fn mul(self, c: Cf) -> Cf {
        Cf::new(self * c.re, self * c.im)
    }
}

